import mujoco, numpy as np, time
base=open("model_ref.xml").read()
def build(optstr):
    return base.replace('<size memory="2M"/>', f'<size memory="2M"/>\n  <option {optstr}><flag contact="disable"/></option>')
def finalstate(m,seed):
    d=mujoco.MjData(m)
    rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    n=int(2.0/m.opt.timestep)
    for i in range(n): mujoco.mj_step(m,d)
    s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS); return s
mref=mujoco.MjModel.from_xml_path("model_ref.xml")
def evalopt(optstr):
    m=mujoco.MjModel.from_xml_string(build(optstr))
    dif=max(np.linalg.norm(finalstate(m,s)-finalstate(mref,s)) for s in [3,17,99])
    ts=[]
    for _ in range(6):
        seed=np.random.randint(0,10000); t=time.perf_counter(); finalstate(m,seed); ts.append(time.perf_counter()-t)
    return dif, np.mean(ts)
# ref timing
tr=[]
for _ in range(6):
    seed=np.random.randint(0,10000); t=time.perf_counter(); finalstate(mref,seed); tr.append(time.perf_counter()-t)
trm=np.mean(tr); print("ref",trm)
for o in ['jacobian="dense"','jacobian="sparse"','solver="CG"','solver="PGS"','solver="CG" jacobian="sparse"','iterations="1"','cone="pyramidal"','jacobian="dense" solver="CG"']:
    try:
        dif,tm=evalopt(o); print(f"{o:35s} diff={dif:.2e} pctg={tm/trm:.3f}")
    except Exception as e:
        print(o,"ERR",e)
EOF

